using UnityEngine;

public class BaseEvent : ScriptableObject, IEvent
{
    public string eventCategory;
    public virtual void Execute() {}

    public virtual void Execute(Node nextNode) {}
}

using System;
public interface IEvent
{
    void Execute();
}

using UnityEngine;

public enum meetingEventType
{
    전투하기,
    무시하기,
    도와주기
}

[CreateAssetMenu(fileName = "MeetingEvent", menuName = "Events/MeetingEvent")]
public class MeetingEvent : BaseEvent
{
    
    public meetingEventType type;
    public CombatNode who;

    public override void Execute(Node nextNode)
    {
        if (NodeManager.Instance != null) {
            switch (type)
            {
                case meetingEventType.전투하기:
                    if (who.enemyData.type == "선")
                    {
                        if (CharacterManager.Instance != null && CharacterManager.Instance.currentPlayer != null)
                        {
                            CharacterManager.Instance.currentPlayer.ChangeTendency(-1);
                        }
                    }
                    Debug.Log($"<color=cyan>[Event] </color>{who.enemyData.name}과(와) 전투를 시작합니다.");
                    who.successNode = nextNode;
                    NodeManager.Instance.GoToNode(who);
                    break;
                case meetingEventType.무시하기:
                    Debug.Log($"<color=cyan>[Event] </color>{who.enemyData.name}을(를) 무시합니다.");
                    NodeManager.Instance.GoToNode(nextNode);
                    break;
                case meetingEventType.도와주기:
                    
                    if (CharacterManager.Instance != null && CharacterManager.Instance.currentPlayer != null)
                    {
                        CharacterManager.Instance.currentPlayer.ChangeTendency(1);
                    }
                    Debug.Log($"<color=cyan>[Event] </color>{who.enemyData.name}을(를) 도와줍니다.");
                    NodeManager.Instance.GoToNode(nextNode);
                    break;
                default:
                    Debug.LogWarning($"<color=cyan>[Event] </color>알 수 없는 EventType입니다.");
                    break;
            }
        }
        
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

[CreateAssetMenu(fileName = "StatUpdateEvent", menuName = "Events/StatUpdateEvent")]
public class StatUpdateEvent : BaseEvent
{
    public int changeAmount;
    public string statType;

    public override void Execute()
    {
        EventExecute();
    }

    public override void Execute(Node nextNode)
    {
        NodeManager.Instance.dumpNode.nextNode = nextNode;
        NodeManager.Instance.dumpNode.surviveDate = nextNode.surviveDate;
        NodeManager.Instance.dumpNode.worldLocation = nextNode.worldLocation;
        EventExecute();
        
    }

    public void EventExecute()
    {
        if (CharacterManager.Instance != null && NodeManager.Instance != null)
        {
            CharacterManager.Instance.currentPlayer.UpdateBaseStats(statType, changeAmount);
            
            NodeManager.Instance.dumpNode.nodeMessage = $"{StatTypeTranslation(statType)}이 {changeAmount}만큼 증가했다!";

            NodeManager.Instance.GoToNode(NodeManager.Instance.dumpNode);
        }
    }
    private string StatTypeTranslation(string statType)
    {
        switch (statType)
            {
                case "str" :
                return "힘";
                case "con" :
                return "체력";
                case "dex" :
                return "민첩";
                default :
                return "에러";
            }
    }
}

#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

// CustomEditor 어트리뷰트를 사용해 MeetingEvent 클래스와 연결
[CustomEditor(typeof(MeetingEvent))]
public class MeetingEventEditor : Editor
{
    // SerializedProperty를 사용해 인스펙터의 변수들을 관리
    SerializedProperty eventCategoryProp;
    SerializedProperty typeProp;
    SerializedProperty whoProp;

    private void OnEnable()
    {
        // 스크립트 활성화 시 변수들을 SerializedProperty로 초기화
        eventCategoryProp = serializedObject.FindProperty("eventCategory");
        typeProp = serializedObject.FindProperty("type");
        whoProp = serializedObject.FindProperty("who");
    }

    public override void OnInspectorGUI()
    {
        // SerializedObject를 업데이트하여 최신 변경사항을 가져옴
        serializedObject.Update();

        // eventCategory와 type 필드를 기본적으로 표시
        EditorGUILayout.PropertyField(eventCategoryProp);
        EditorGUILayout.PropertyField(typeProp);

        // type이 '전투하기'일 때만 who 필드를 표시
        // Enum 값은 정수로 변환하여 비교
        if (typeProp.enumValueIndex == (int)meetingEventType.전투하기)
        {
            EditorGUILayout.PropertyField(whoProp);
        }

        // 변경사항을 SO에 적용
        serializedObject.ApplyModifiedProperties();
    }
}
#endif
